<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Great Wave — low-poly wallpaper</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Shippori+Mincho:wght@500;700&display=swap" rel="stylesheet">
<style>
  :root { --paper:#eee3c9; --ink:#14395c; --deep:#0e2f4f; }
  html, body { margin:0; height:100%; overflow:hidden; background:var(--paper); }
  #app { position:fixed; inset:0; }
  canvas { display:block; width:100%; height:100%; }
  .grain, .vignette { position:fixed; inset:0; pointer-events:none; }
  .grain {
    opacity:.16; mix-blend-mode:multiply;
    background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='0.55'/></svg>");
  }
  .vignette { background:radial-gradient(120% 100% at 50% 45%, transparent 55%, rgba(72,52,26,.16) 100%); }
  .cartouche {
    position:fixed; top:clamp(14px,3.2vh,34px); left:clamp(14px,2.4vw,34px);
    display:flex; gap:.55em; padding:.6em .55em; color:var(--ink);
    background:rgba(242,233,210,.88);
    border:1.5px solid var(--ink); box-shadow:2px 2px 0 rgba(20,57,92,.25);
    font-family:"Shippori Mincho","Hiragino Mincho ProN",serif;
    writing-mode:vertical-rl; text-orientation:upright;
    font-size:clamp(11px,1.55vw,16px); letter-spacing:.16em; line-height:1.25;
    user-select:none;
  }
  .cartouche .seal { font-weight:700; border-right:1px solid rgba(20,57,92,.45); padding-right:.5em; }
  .cartouche .sig { font-size:.8em; opacity:.85; }
  @media (max-width:520px){ .cartouche{ transform:scale(.82); transform-origin:top left; } }
</style>
</head>
<body>
<div id="app" role="img" aria-label="Low-poly 3D wallpaper after Hokusai's Great Wave off Kanagawa: a towering indigo wave curls from the left over three small wooden boats, with Mount Fuji low in the distance on cream paper sky."></div>
<div class="grain"></div>
<div class="vignette"></div>
<div class="cartouche" aria-hidden="true">
  <span class="seal">冨嶽三十六景</span>
  <span>神奈川沖浪裏</span>
  <span class="sig">北斎画</span>
</div>

<script type="module">
