camera.position.set(0, 0, 30);
camera.lookAt(0, 0, 0);

const world = new THREE.Group();
scene.add(world);

/* lighting: soft gallery light, strong ambient so the poster colours stay flat */
scene.add(new THREE.HemisphereLight(0xfff7e4, 0x284257, 1.45));
